cat > project/src/replay_api.c <<'EOF'
#include "star4_switch.c"

void *epic_open(int primitive, int mode, int root, uint32_t count, uint32_t words,
                uint32_t capacity, uint32_t start, epic_emit_fn emit, void *user) {
    switch_ctx_t *c = calloc(1, sizeof(*c));
    if (!c) return NULL;
    c->primitive = primitive; c->mode = mode; c->root = root;
    c->count = count; c->words = words; c->capacity = capacity; c->start = start;
    c->emit = emit; c->user = user;
    /* Give barrier a harmless nonzero stride, avoiding null pointer arithmetic. */
    c->stride = words ? (size_t)4 * words * (primitive == EPIC_PRIM_ALLGATHER ? 4 : 1) : 4;
    c->slots = calloc(capacity, sizeof(*c->slots));
    c->payloads = calloc(capacity, c->stride);
    if (!c->slots || !c->payloads) {
        free(c->slots); free(c->payloads); free(c); return NULL;
    }
    for (int r = 0; r < 4; ++r) {
        epic_port_t *p = &c->ports[r]; p->rank = r;
        p->host_mac[0] = 2; p->host_mac[5] = r + 1;
        p->switch_mac[0] = 2; p->switch_mac[1] = 1; p->switch_mac[5] = r + 1;
        p->host_ip = htonl(0x0a000001u + r); p->switch_ip = htonl(0x0a000065u + r);
        p->host_qpn = 0x100u + r; p->switch_qpn = 0x200u + r;
    }
    return c;
}
void epic_close(void *context) {
    switch_ctx_t *c = context;
    if (c) { free(c->slots); free(c->payloads); free(c); }
}
int epic_ingress(void *context, int rank, const uint8_t *frame, size_t length) {
    return handle_packet(context, rank, frame, length);
}
int epic_flush(void *context) { return service(context, -1); }
int epic_retry(void *context, int rank) {
    switch_ctx_t *c = context;
    c->repeat[rank] = true;
    return service(c, rank);
}
void epic_state(void *context, uint64_t *state) {
    switch_ctx_t *c = context;
    state[0] = c->retired; state[1] = c->occupied;
    for (int r = 0; r < 4; ++r) {
        state[2+r] = c->received[r]; state[6+r] = c->sent[r];
        state[10+r] = c->acked[r]; state[14+r] = c->upstream[r];
    }
    memcpy(state+18, c->counters, sizeof(c->counters));
}
static uint64_t fold_byte(uint64_t h, uint8_t value) {
    return (h ^ value) * UINT64_C(1099511628211);
}
static uint64_t fold_le(uint64_t h, uint64_t value, int bytes) {
    for (int j = 0; j < bytes; ++j) { h = fold_byte(h, (uint8_t)value); value >>= 8; }
    return h;
}
static uint64_t fold_raw(uint64_t h, const uint8_t *data, size_t bytes) {
    for (size_t j = 0; j < bytes; ++j) h = fold_byte(h, data[j]);
    return h;
}
uint64_t epic_digest(void *context) {
    switch_ctx_t *c = context;
    uint64_t h = UINT64_C(14695981039346656037);
    uint32_t end = min32(c->count, c->retired + c->capacity);
    for (uint32_t p = c->retired; p < end; ++p) {
        slot_state_t *s = find_slot(c, p);
        if (!s) continue;
        h = fold_le(h, p, 8);
        h = fold_byte(h, s->mask);
        h = fold_byte(h, complete(c, s));
        uint8_t *data = slot_payload(c, p);
        if (c->primitive == EPIC_PRIM_ALLGATHER) {
            for (int r = 0; r < 4; ++r) {
                bool present = (s->mask & BIT(r)) != 0;
                h = fold_byte(h, present);
                if (present) h = fold_raw(h, data + r * c->words * 4, c->words * 4);
            }
        } else if (c->primitive == EPIC_PRIM_BCAST) h = fold_raw(h, data, c->words * 4);
        else {
            uint32_t *accum = (uint32_t *)data;
            for (uint32_t j = 0; j < c->words; ++j) h = fold_le(h, accum[j], 4);
        }
    }
    return h;
}
